package main

import (
	"context"
	"errors"
	"fmt"
	"time"
)

type traceKey struct{}

func worker(ctx context.Context, name string) string {
	select {
	case <-ctx.Done():
		return name + " 取消: " + ctx.Err().Error()
	case <-time.After(30 * time.Millisecond):
		return name + " 完成, trace=" + ctx.Value(traceKey{}).(string)
	}
}

func main() {
	ctx, cancel := context.WithTimeout(context.Background(), time.Second)
	defer cancel()
	ctx = context.WithValue(ctx, traceKey{}, "req-1")
	fmt.Println(worker(ctx, "任务A"))

	child, cancelChild := context.WithCancelCause(ctx)
	cancelChild(errors.New("用户退出"))
	fmt.Println("取消原因:", context.Cause(child))
	fmt.Println("是超时吗:", errors.Is(child.Err(), context.DeadlineExceeded))
}
